define('taoQtiItem/qtiCreator/widgets/interactions/inlineChoiceInteraction/ResponseWidget',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCommonRenderer/renderers/Renderer', 'taoQtiItem/qtiCreator/widgets/helpers/placeholder'], function ($, _, __, CommonRenderer, placeholder) {
  'use strict';

  var ResponseWidget = {
    create: function create(widget, responseMappingMode, callback) {
      var self = this;
      var interaction = widget.element;
      var $placeholder = $('<select>');
      var $responseWidget = widget.$container.find('.widget-response').append($placeholder);
      this.commonRenderer = new CommonRenderer({
        shuffleChoices: false,
        themes: false
      });
      if (responseMappingMode) {
        widget.on('mappingAttributeChange', function (data) {
          if (data.key === 'defaultValue') {
            placeholder.score(widget, data.value);
          }
        });
        placeholder.score(widget);
      }
      this.commonRenderer.load(function () {
        interaction.render({}, $placeholder, '', this);
        interaction.postRender({
          allowEmpty: false,
          placeholderText: __('select correct choice')
        }, '', this);
        callback.call(self, this);
        $responseWidget.siblings('.padding').width($responseWidget.width() + 50);
      }, ['inlineChoice', 'inlineChoiceInteraction', '_container', 'math']);
    },
    setResponse: function setResponse(widget, response) {
      this.commonRenderer.setResponse(widget.element, this.formatResponse(response));
    },
    destroy: function destroy(widget) {
      widget.$container.find('.widget-response').empty();
      widget.$container.find('.padding').removeAttr('style');
    },
    formatResponse: function formatResponse(response) {
      if (!_.isString(response)) {
        response = _.values(response);
        if (response && response.length) {
          response = response[0];
        }
      }
      return {
        base: {
          identifier: response
        }
      };
    },
    unformatResponse: function unformatResponse(formatedResponse) {
      var response = [];
      if (formatedResponse.base && formatedResponse.base.identifier) {
        response.push(formatedResponse.base.identifier);
      }
      return response;
    }
  };
  return ResponseWidget;
});
