define('taoQtiItem/qtiCreator/plugins/navigation/back',['jquery', 'i18n', 'util/url', 'core/plugin', 'ui/hider', 'tpl!taoQtiItem/qtiCreator/plugins/button'], function ($, __, urlUtil, pluginFactory, hider, buttonTpl) {
  'use strict';
  function wasOpenedViaAutoAction() {
    var parsedUrl = urlUtil.parse(window.location.href);
    return !!parsedUrl.query.autoAction;
  }
  return pluginFactory({
    name: 'back',
    init: function init() {
      var itemCreator = this.getHost();
      var openedViaAutoAction = wasOpenedViaAutoAction();
      itemCreator.on('exit', function () {
        if (openedViaAutoAction) {
          window.close();
        } else {
          window.history.back();
        }
      });
      var buttonTitle = openedViaAutoAction ? __('Back to test authoring') : __('Back to Manage Items');
      var buttonText = openedViaAutoAction ? __('Close') : __('Manage Items');
      this.$element = $(buttonTpl({
        icon: 'left',
        title: buttonTitle,
        text: buttonText,
        cssClass: 'back-action',
        testId: 'manage-items'
      })).on('click', function backHandler(e) {
        e.preventDefault();
        itemCreator.trigger('exit');
      });
      this.hide();
    },
    render: function render() {
      var $container = this.getAreaBroker().getMenuLeftArea();
      $container.append(this.$element);
      this.show();
    },
    destroy: function destroy() {
      this.$element.remove();
    },
    enable: function enable() {
      this.$element.removeProp('disabled').removeClass('disabled');
    },
    disable: function disable() {
      this.$element.prop('disabled', true).addClass('disabled');
    },
    show: function show() {
      hider.show(this.$element);
    },
    hide: function hide() {
      hider.hide(this.$element);
    }
  });
});
